            if (WeekendDays.HasFlag(WeekendDay.Tuesday)) days.Add(isFa ? "سهشنبه" : "Tuesday");
            if (WeekendDays.HasFlag(WeekendDay.Wednesday)) days.Add(isFa ? "چهارشنبه" : "Wednesday");
            if (WeekendDays.HasFlag(WeekendDay.Thursday)) days.Add(isFa ? "پنجشنبه" : "Thursday");
