using Setak.IMS.Classes.DTOs.Pub;

namespace Setak.IMS.Blazor.UI.Pages.EquipmentOutField;

public partial class Editor : IAsyncDisposable
{
    #region Fields

    private bool isInitialized = false;
    private bool isFirstRender = false;
    private bool isDisposed = false;

    private EquipmentOutFieldDto? model = null;
    private Dictionary<WeekendDay, bool> _weekendFlags = new();

    private Validations validationsRef;
    private PageLoading loadingRef;

    #endregion

    //***********************************************************

    #region Properties

    public bool IsLoading => !(isInitialized && isFirstRender);

    [Parameter]
    [EditorRequired]
    public string Title { get; set; }

    [Parameter]
    [EditorRequired]
    public string AuthorizePolicy { get; set; }

    [Parameter]
    [EditorRequired]
    public EquipmentOutFieldDto Data
    {
        get => model!;
        set => model = value;
    }

    [Parameter]
    public Func<Task>? OnSubmit { get; set; }

    #endregion

    //***********************************************************

    #region Methods

    public ValueTask DisposeAsync()
    {
        isDisposed = true;
        GC.SuppressFinalize(this);
        return ValueTask.CompletedTask;
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            isInitialized = true;
            await base.OnInitializedAsync();
        }
        catch (Exception ex)
        {
            ErrorState.SetError(ex);
        }
    }


    protected override async Task OnParametersSetAsync()
    {
        try
        {
            if (model != null)
            {
                SyncFlagsFromModel();
                isInitialized = true;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (Exception ex)
        {
            ErrorState.SetError(ex);
        }
    }

    //-------------------- Private Methods ----------------------

    private void SyncFlagsFromModel()
    {
        _weekendFlags.Clear();
        foreach (WeekendDay wd in Enum.GetValues<WeekendDay>())
        {
            if (wd == WeekendDay.None) continue;
            _weekendFlags[wd] = model?.WeekendDays.HasFlag(wd) ?? false;
        }
    }

    private void ToggleWeekend(WeekendDay wd)
    {
        _weekendFlags[wd] = !_weekendFlags[wd];
        RebuildWeekendDays();
    }

    private void RebuildWeekendDays()
    {
        if (model == null) return;
        model.WeekendDays = WeekendDay.None;
        foreach (var kvp in _weekendFlags)
        {
            if (kvp.Value && kvp.Key != WeekendDay.None)
                model.WeekendDays |= kvp.Key;
        }
    }

    private string GetWeekendDayName(WeekendDay wd)
    {
        bool isFa = System.Globalization.CultureInfo.CurrentUICulture.Name == "fa-IR";
        return wd switch
        {
            WeekendDay.Saturday   => isFa ? "شنبه" : "Saturday",
            WeekendDay.Sunday    => isFa ? "یکشنبه" : "Sunday",
            WeekendDay.Monday    => isFa ? "دوشنبه" : "Monday",
            WeekendDay.Tuesday   => isFa ? "سهشنبه" : "Tuesday",
            WeekendDay.Wednesday => isFa ? "چهارشنبه" : "Wednesday",
            WeekendDay.Thursday  => isFa ? "پنجشنبه" : "Thursday",
            WeekendDay.Friday    => isFa ? "جمعه" : "Friday",
            _ => wd.ToString()
        };
    }

    private async Task SubmitAsync()
    {
        try
        {
            RebuildWeekendDays();

            bool isValidate = await validationsRef.ValidateAll().ConfigureAwait(false);
            if (!isValidate) return;

            await validationsRef.ClearAll().ConfigureAwait(false);
            await loadingRef.Show().ConfigureAwait(false);

            if (OnSubmit != null)
            {
                await OnSubmit.Invoke().ConfigureAwait(false);
            }

            await loadingRef.Hide().ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            ErrorState.SetError(ex);
        }
    }

    #endregion
}"}
